class Solution:
    def numberOfArithmeticSlices(self, nums: List[int]) -> int:
        ans = 0
        table = [0] * len(nums)

        for r in range(2, len(nums)):
            diff1 = nums[r] - nums[r-1]
            diff2 = nums[r-1] - nums[r-2]

            if diff1 == diff2:
                table[r] = table[r-1] + 1
                ans += table[r-1] + 1

        return ans

class Solution:
    def numberOfArithmeticSlices(self, A):
        res, i = 0, 0
        while i+2 < len(A):
            start = i
            while i+2 < len(A) and A[i+2] + A[i] == 2*A[i+1]:
                res += i - start + 1
                i += 1
            i += 1

        return res

